const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeOkeechobee = ee.Geometry.Polygon(
    [[[-81.082269, 27.133291],
      [-80.457811, 27.133291],
      [-80.457811, 26.687258],
      [-81.082269, 26.687258],
      [-81.082269, 27.133291]]]); // Bounding box for Lake Okeechobee

  const startDate = '2023-06-12';
  const endDate = '2023-06-13'; // To capture images on June 12th

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S3/OLCI/L2_WFR')
    .filterBounds(lakeOkeechobee)
    .filterDate(startDate, endDate);

  const initialSize = collection.size().getInfo();
  if (initialSize === 0) {
    console.log("No Sentinel-3 OLCI images found for Lake Okeechobee on June 12, 2023.");
    console.log("C1");
    return;
  }

  // Select the least cloudy image if multiple exist
  // S3 OLCI L2 WFR does not have a direct 'cloud_percentage' band.
  // We'll rely on the quality_flags band to mask out clouds.
  // For simplicity and to ensure we get an image, we'll take the first image
  // after filtering, assuming a single day filter is restrictive enough.
  let image = collection.first();

  // Define a chlorophyll-a threshold for cyanobacteria presence.
  // Common thresholds for bloom conditions vary, but >20 ug/L is often considered a bloom.
  // For 'covered', we'll use a relatively low threshold of 10 ug/L to signify 'presence'.
  const CHLA_THRESHOLD_UG_L = 10; // Chlorophyll-a concentration in µg/L

  // Masking function for S3 OLCI L2_WFR products
  // Based on quality_flags (extracted from bitmasks)
  // Flags to check: CLOUDY_OCEAN, CLOUDY_LAND, CLOUD_AMBIGUOUS, CLOUD_MARGIN, INVALID, LAND, SUSPECT_Rrs
  const maskOlciCloudsAndLand = function(image) {
    const qualityFlags = image.select('quality_flags');
    const cloudMask = qualityFlags.bitwiseAnd(1 << 0) // CLOUDY_OCEAN
      .or(qualityFlags.bitwiseAnd(1 << 1)) // CLOUDY_LAND
      .or(qualityFlags.bitwiseAnd(1 << 2)) // CLOUD_AMBIGUOUS
      .or(qualityFlags.bitwiseAnd(1 << 3)) // CLOUD_MARGIN
      .or(qualityFlags.bitwiseAnd(1 << 4)) // INVALID
      .or(qualityFlags.bitwiseAnd(1 << 5)) // LAND
      .or(qualityFlags.bitwiseAnd(1 << 6)); // SUSPECT_Rrs (can be related to clouds/land adjacency)

    // Invert the mask: 0 for valid pixels, 1 for invalid (cloud/land/etc)
    return image.updateMask(cloudMask.eq(0));
  };

  image = maskOlciCloudsAndLand(image).clip(lakeOkeechobee);

  // Select the chlorophyll-a band (chla_nn in µg/L)
  const chla = image.select('chla_nn');

  // 3. Processing
  // Calculate total valid water pixels
  const totalWaterPixels = chla.gt(-9999) // Filter out nodata values
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeOkeechobee,
      scale: 300, // S3 OLCI resolution is ~300m
      maxPixels: 1e9,
    })
    .get('chla_nn');

  const totalWaterPixelsCount = totalWaterPixels.getInfo();

  if (totalWaterPixelsCount === null || totalWaterPixelsCount === 0) {
    console.log(`Initial Images: ${initialSize}`);
    console.log("No valid water pixels remaining after cloud/land masking for Lake Okeechobee.");
    console.log("C2");
    return;
  }

  // Calculate pixels with cyanobacteria (chla_nn > CHLA_THRESHOLD_UG_L)
  const cyanobacteriaPixels = chla.gt(CHLA_THRESHOLD_UG_L)
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeOkeechobee,
      scale: 300,
      maxPixels: 1e9,
    })
    .get('chla_nn'); // Sum of 1s where condition is true

  const cyanobacteriaPixelsCount = cyanobacteriaPixels.getInfo();

  // 4. Calculation
  if (cyanobacteriaPixelsCount === null || typeof cyanobacteriaPixelsCount === 'undefined') {
    console.log(`Initial Images: ${initialSize}`);
    console.log(`Total Water Pixels: ${totalWaterPixelsCount}`);
    console.log("Calculation for cyanobacteria pixels returned null/undefined.");
    console.log("C3");
    return;
  }

  const percentageCovered = (cyanobacteriaPixelsCount / totalWaterPixelsCount) * 100;

  // 5. Validation & Final Answer
  console.log(`Initial S3 Images: ${initialSize}`);
  console.log(`Date: ${startDate}`);
  console.log(`Total Valid Water Pixels: ${totalWaterPixelsCount}`);
  console.log(`Pixels with Chl-a > ${CHLA_THRESHOLD_UG_L} µg/L: ${cyanobacteriaPixelsCount}`);
  console.log(`Percentage Covered: ${percentageCovered.toFixed(2)}%`);

  if (percentageCovered > 30) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
